 public static void Core(string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"glass-core-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);var log=new List<string>();Action<bool,string> check=(ok,text)=>{log.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(path,log.ToArray());if(!ok)throw new Exception(text);};try{File.WriteAllText(Path.Combine(Engine.DataRoot,"settings-ver1.2.1.tsv"),"font\t20\nauto\t0\n");AppSettings.Load();check(AppSettings.EditorFont==20&&!AppSettings.AutoCheck&&!AppSettings.Night,"Old version settings migrate with light theme default");AppSettings.SetNight(true);typeof(AppSettings).GetField("loaded",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);check(AppSettings.Night&&AppSettings.EditorFont==20&&!AppSettings.AutoCheck,"Theme, font and automatic update preference reload from disk");Version version;check(UpdateService.TryVersion("ver1.2.1.1",out version)&&version==UpdateService.Current&&version>new Version(1,2,1,0),"Four component version correctly compares to previous release");string raw="{\"tag_name\":\"ver1.2.1.2\",\"draft\":false,\"prerelease\":false,\"body\":\"test\",\"assets\":[{\"name\":\"Feng_C_Practice_ver1.2.1.2.exe\",\"state\":\"uploaded\",\"size\":4096,\"browser_download_url\":\"https://github.com/relsx/feng-c-practice/releases/download/ver1.2.1.2/Feng_C_Practice_ver1.2.1.2.exe\"}]}";var release=UpdateService.Parse(raw);check(release.Newer&&release.CanInstall&&release.VersionText=="1.2.1.2","Four component Release asset filenames retain revision number");check(!UpdateService.Parse(raw.Replace("1.2.1.2","1.2.1")).Newer,"Published ver1.2.1 cannot downgrade this build");int count=0;foreach(int id in new[]{1,40,90}){var p=Bank.All().First(x=>x.Id==id);var ev=Engine.Judge(p,p.Reference,1211,CancellationToken.None,(a,b)=>{});check(ev.Compiled&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Passed),"Ordinary reference compilation and 28 cases: "+id);count+=ev.Cases.Count;}foreach(int n in new[]{1,25,50}){var l=ChallengeBank.Levels[n-1];var ev=Engine.Judge(l.Problem,l.Problem.Reference,1211,CancellationToken.None,(a,b)=>{});check(ChallengeProgress.Qualifies(ev)&&ev.Cases.All(c=>c.Passed),"Challenge reference compilation, passing score and 28 cases: "+n);count+=ev.Cases.Count;}check(true,"Core regression cases passed: "+count);log.Add("ALL GLASS CORE CHECKS PASSED");File.WriteAllLines(path,log.ToArray());}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray());Environment.ExitCode=1;}}
 static T Field<T>(object obj,string name){return (T)obj.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 static IEnumerable<T> All<T>(DependencyObject node) where T:DependencyObject{if(node is T)yield return (T)node;for(int i=0;i<VisualTreeHelper.GetChildrenCount(node);i++)foreach(var n in All<T>(VisualTreeHelper.GetChild(node,i)))yield return n;}
 public static void Run(Application app,string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"glass-state-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Engine.DataRoot);AppSettings.Load();GlassTheme.Apply(false,false);var lines=new List<string>();Action<bool,string> check=(ok,text)=>{lines.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines(path,lines.ToArray());if(!ok)throw new Exception(text);};var main=new MainWindow(true);main.ContentRendered+=async(s,e)=>{try{
  await Transitions.WhenReady(main);check(main.WindowStyle==WindowStyle.None&&WindowChrome.GetWindowChrome(main)!=null,"Integrated borderless chrome with native resize support");var editor=Field<CodeEditor>(main,"editor");main.PreviewSize(1600,1000);await Task.Delay(100);check(GlassChrome.CornersAligned(main),"Main native corner region matches the glass frame and clipping geometry");var mainIcons=All<Button>(main).ToList();var settingsIcon=mainIcons.First(b=>(b.Tag as string)=="icon:设置");var maximize=mainIcons.First(b=>AutomationProperties.GetName(b)=="最大化 / 还原");double settingsY=settingsIcon.TranslatePoint(new Point(0,settingsIcon.ActualHeight/2),main).Y,maximizeY=maximize.TranslatePoint(new Point(0,maximize.ActualHeight/2),main).Y;check(Math.Abs(settingsY-maximizeY)<=1,"Main settings icon and window controls share one centre line");string code="#include <stdio.h>\nint main(void)\n{\n    int value = 12;\n    printf(\"%d\", value);\n    return 0;\n}\n";editor.Text=code;editor.Input.CaretOffset=code.IndexOf("int value");editor.Input.SelectedText=" ";string edited=editor.Text;int caret=editor.Input.CaretOffset;var document=editor.Input.Document;bool undo=editor.CanUndo;
  Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"明亮主界面.png"),153.6);
  var settings=new SettingsWindow(false,true){Owner=main};settings.Show();await Transitions.WhenReady(settings);check(GlassChrome.CornersAligned(settings),"Settings native corner region matches the glass frame and clipping geometry");check(All<GlassCard>(settings).All(c=>{var child=c.Child as FrameworkElement;var clip=child==null?null:child.Clip as RectangleGeometry;return clip!=null&&Math.Abs(clip.Rect.Width-child.ActualWidth)<.1&&Math.Abs(clip.Rect.Height-child.ActualHeight)<.1;}),"Settings card backgrounds and inner clipping stay aligned");check(Transitions.Duration(settings)==500,"Settings opening fade is 500ms");Field<Button>(settings,"nightMode").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(340);check(AppSettings.Night&&editor.Input.Document==document&&editor.Text==edited&&editor.Input.CaretOffset==caret&&editor.CanUndo==undo,"Theme toggle retains editor document, text, caret and undo");check(((SolidColorBrush)Theme.Ink).Color.R>200,"Dark mode uses readable light text");check(File.ReadAllText(Path.Combine(Engine.DataRoot,"settings-ver1.2.1.tsv")).Contains("theme\tdark"),"Theme preference saved alongside compatible font settings");Theme.Capture((FrameworkElement)settings.Content,Path.Combine(Path.GetDirectoryName(path),"深色设置.png"),144);settings.Close();check(settings.IsVisible,"Closing animation delays final close");await Task.Delay(240);check(!settings.IsVisible,"Settings closes after fade");Theme.Capture((FrameworkElement)main.Content,Path.Combine(Path.GetDirectoryName(path),"深色主界面.png"),153.6);
  var game=new ChallengeWindow(true){Owner=main};game.Show();await Transitions.WhenReady(game);game.PreviewSize(1600,1000);game.StartForCheck();check(game.IsAttemptRunning&&Field<ConstellationMap>(game,"map").IsEnabled,"Challenge countdown retains dark enabled constellation");game.StartForCheck();AppSettings.SetNight(false);await Task.Delay(330);check(GlassChrome.IsDark(game)&&((SolidColorBrush)game.FindResource("GlassInk")).Color.R>200,"Challenge stays dark while ordinary mode switches to light");Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"暗域玻璃星轨.png"),153.6);
  var buttons=All<Button>(main).Where(b=>b.Tag is string&&((string)b.Tag).StartsWith("icon:")).ToList();check(buttons.Count>=10&&buttons.All(b=>b.ToolTip!=null&&AutomationProperties.GetName(b)!=""&&b.Width>=32),"All compact icon commands retain tooltip, accessibility name and hit area");foreach(string command in new[]{"设置","知识点学习","提示 / 标准答案","撤回","取消撤回","导入","保存","重置","查看结果与报告"})check(buttons.Any(b=>(string)b.Tag=="icon:"+command),"Icon command available: "+command);
  var answer=new AnswerWindow(Bank.All()[0]){Owner=main};answer.Show();await Transitions.WhenReady(answer);check(answer.AnswerEditor.Visibility==Visibility.Collapsed&&!answer.ImportButton.IsEnabled,"Reference remains hidden until hints are read");answer.Reveal.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(300);check(answer.AnswerEditor.Visibility==Visibility.Visible&&answer.ImportButton.IsEnabled,"Reference reveal command and animation work");Theme.Capture((FrameworkElement)answer.Content,Path.Combine(Path.GetDirectoryName(path),"提示与答案.png"),144);answer.ImportButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(230);check(answer.ImportAnswer&&!answer.IsVisible,"Answer import intent survives animated close");
  var knowledge=new KnowledgeWindow(Bank.All()[40]){Owner=main};knowledge.Show();await Transitions.WhenReady(knowledge);var tabs=All<TabControl>(knowledge).First();tabs.SelectedIndex=1;await Task.Delay(280);check(tabs.SelectedIndex==1,"Knowledge page tab transition keeps navigation working");Theme.Capture((FrameworkElement)knowledge.Content,Path.Combine(Path.GetDirectoryName(path),"知识点学习.png"),144);knowledge.Close();await Task.Delay(230);
  var popup=new AppDialog("动画关闭后仍保留选择结果。","对话框验证",MessageBoxButton.YesNo){Owner=main};popup.Show();await Transitions.WhenReady(popup);popup.AffirmativeButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));await Task.Delay(230);check(!popup.IsVisible&&popup.Result==MessageBoxResult.Yes,"Confirmation result survives animated close");
  var modal=new AppDialog("请选择确定。","模态关闭验证",MessageBoxButton.OKCancel){Owner=main};var clickTimer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(550)};clickTimer.Tick+=(a,b)=>{clickTimer.Stop();modal.AffirmativeButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));};clickTimer.Start();modal.ShowDialog();check(modal.Result==MessageBoxResult.OK&&!modal.IsVisible,"Real modal dialog returns correct result after animated close");
  bool block=true;var guarded=new AppDialog("关闭保护验证。","关闭保护"){Owner=main};guarded.Closing+=(a,b)=>{if(block)b.Cancel=true;};guarded.Show();await Transitions.WhenReady(guarded);guarded.Close();await Task.Delay(240);check(guarded.IsVisible&&((FrameworkElement)guarded.Content).IsHitTestVisible,"Existing close cancellation keeps the window usable");block=false;guarded.Close();await Task.Delay(230);check(!guarded.IsVisible,"Close completes normally once guard is released");
  int hits=0;editor.Text=game.Editor.Text=code;foreach(bool night in new[]{false,true}){AppSettings.SetNight(night);await Task.Delay(320);foreach(double dpi in new[]{96.0,144.0,192.0}){double w=2560*96/dpi,h=1600*96/dpi;main.PreviewSize(w,h);game.PreviewSize(w,h);foreach(int size in AppSettings.FontSizes){AppSettings.SetFont(size);main.UpdateLayout();game.UpdateLayout();await Task.Delay(30);foreach(var ed in new[]{editor,game.Editor}){ed.Input.ScrollToHome();ed.RefreshView();for(int i=0;i<code.Length-1;i++){if(code[i]=='\n'||code[i+1]=='\n')continue;var a=ed.Input.CharacterRect(i);var b=ed.Input.CharacterRect(i+1);if(b.X<=a.X)continue;int hit=ed.Input.Hit(new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height*.5));if(hit!=i)throw new Exception("Caret geometry mismatch: "+night+" / "+dpi+" / "+size+" / "+i);hits++;}}}check(editor.ActualHeight>160&&game.Editor.ActualHeight>160,"Both editor layouts stay usable at "+dpi+"dpi / dark="+night);}}
  check(hits>5000,"Cursor positions match at 6 fonts × 3 DPI scales × 2 themes × 2 modes: "+hits);AppSettings.SetNight(false);AppSettings.SetFont(16);game.Close();await Task.Delay(230);var light=new SettingsWindow(false,true){Owner=main};light.Show();await Transitions.WhenReady(light);Theme.Capture((FrameworkElement)light.Content,Path.Combine(Path.GetDirectoryName(path),"明亮设置.png"),144);light.Close();await Task.Delay(230);main.PreviewSize(1600,1000);await Task.Delay(120);lines.Add("ALL GLASS UI CHECKS PASSED");File.WriteAllLines(path,lines.ToArray());main.Close();
 }catch(Exception ex){lines.Add("FAIL "+ex);File.WriteAllLines(path,lines.ToArray());app.Shutdown(1);}};app.Run(main);}
